export type Language = "id" | "en";

/**
 * Chrome-level (nav/sidebar/status/login) strings, plus the Carbon module
 * (features/carbon/** + the AOI tabs it shares) under the `carbon.*`
 * namespace - the first feature module to get full EN parity (see
 * MIGRATION.md "Known deviations" / follow-up #7). The legacy app's
 * `I18N_EXACT` + `LULC_CLASS_TRANSLATIONS` dictionaries (main.js) cover
 * hundreds of additional analysis-result strings for OTHER modules
 * (vegetation/landcover-as-standalone, disaster, crop-monitoring, imagery,
 * lc-change, admin) that are NOT ported here yet - those modules should
 * extend this dictionary under their own key namespace as they're migrated.
 */
