    "lc.fusion.commonPathTitle": "Jalur bersama:",
    "lc.fusion.commonPathHelp": "jalur dipilih dari kualitas pada t₀ dan t₁, lalu pengklasifikasi yang sama membandingkan kedua periode agar perpindahan sensor tidak dianggap sebagai perubahan.",
    "lc.fusion.coverageNote": "Klasifikasi dibatasi pada cakupan MapBiomas Indonesia 4.1. Hasil belum mewakili akurasi independen dan perlu validasi lapangan.",
    "lc.fusion.description": "Q_o = V_o × (1 − C_o) × A_o (Sentinel-2); Q_s = V_s × S_s × A_s (Sentinel-1); keduanya berada pada rentang 0–1 dan bernilai 0 bila tidak ada pengamatan valid. Untuk menetapkan perubahan, sistem menentukan satu jalur bersama dari kedua periode sekaligus: gabungan bila optik dan radar sama-sama memenuhi q_min pada t0 dan t1, optik atau radar bila hanya satu sumber yang memenuhi q_min pada kedua periode, selain itu tanpa data. Pengklasifikasi yang sama menghasilkan P(t0) dan P(t1), sehingga pergantian model antarperiode tidak dihitung sebagai perubahan. Perubahan valid bila D = ½ Σ |P_t0,k − P_t1,k| ≥ tau dan kelas teratasnya berbeda. Hanya piksel di dalam cakupan peta MapBiomas Indonesia 4.1 yang diklasifikasi. Proses pertama melatih pengklasifikasi dan dapat berlangsung beberapa menit.",
