    "admin.fieldCalibration.guideText": "Pisahkan plot kalibrasi dan validasi sejak awal. Catat persamaan allometri, rasio akar:tajuk, metode laboratorium, sumber, luas, dan tanggal untuk setiap pengamatan. Ringkasan mencakup seluruh kunjungan. Kalibrasi memerlukan minimal tiga plot; validasi terpisah memerlukan minimal dua plot lain. Evaluasi memeriksa kesesuaian tahun, dukungan spasial, dan kedalaman SOC.",
