    "admin.fieldCalibration.extractHelp": "Sistem memilih model GEE aktif yang telah dievaluasi dan disetujui secara independen untuk pool ini. Untuk batch berikutnya, naikkan offset sesuai jumlah plot per batch. Jika tersedia, sistem memakai geometri plot tersimpan; jika tidak, sistem membentuk lingkaran dengan luas setara dari titik koordinat dan luas plot. Hasil disimpan sebagai snapshot prediksi berversi dan tidak menimpa snapshot sebelumnya. Setelah ekstraksi, pasangan dievaluasi otomatis terhadap plot kalibrasi dan validasi. SOC hanya dibandingkan pada kedalaman yang Anda isi; plot tanpa pasangan yang sesuai tetap dilaporkan sebagai pengecualian. Evaluasi otomatis tidak membuat kandidat kalibrasi. Jalankan evaluasi manual setelah semua batch tersedia untuk membuat kandidat.",
