    "lc.fusion.qualityOpticalHelp": "Vₒ marks a clear observation, Cₒ is median cloud probability, and Aₒ measures observation sufficiency.",
    "lc.fusion.qualitySarTitle": "Radar quality · Sentinel-1",
    "lc.fusion.qualitySarHelp": "Vₛ marks valid radar data, Sₛ measures filtered backscatter consistency, and Aₛ measures observation sufficiency.",
    "lc.fusion.changeRuleTitle": "Valid-change rule",
    "lc.fusion.changeRuleHelp": "A change is valid when D ≥ τ ({tau}) and the highest-probability class differs between periods.",
    "lc.fusion.commonPathTitle": "Common path:",
    "lc.fusion.commonPathHelp": "the path is selected from quality at t₀ and t₁, then the same classifier compares both periods so a sensor switch is not counted as change.",
    "lc.fusion.coverageNote": "Classification is limited to MapBiomas Indonesia 4.1 coverage. Independent accuracy has not been established; field validation is needed.",
    "lc.fusion.description": "Q_o = V_o × (1 − C_o) × A_o (Sentinel-2); Q_s = V_s × S_s × A_s (Sentinel-1); both lie in 0–1 and are 0 without a valid observation. To decide change, one common path is chosen from both periods at once: joint when optical and radar both meet q_min in t0 and t1, optical or radar when only one source meets q_min in both periods, otherwise no data. The same classifier produces P(t0) and P(t1), so a model switch between periods is never counted as change. A change is valid when D = ½ Σ |P_t0,k − P_t1,k| ≥ tau and the top classes differ. Only pixels inside the MapBiomas Indonesia 4.1 coverage are classified. The first run trains the classifiers and may take several minutes.",
    "lc.fusion.needAoi": "Choose an AOI and two different years (t0 must be earlier than t1) first.",
